void nfsd4_init_cb ( struct nfsd4_callback * cb , struct nfs4_client * clp , const struct nfsd4_callback_ops * ops , enum nfsd4_cb_op op ) { cb -> cb_clp = clp ; cb -> cb_msg . rpc_proc = & nfs4_cb_procedures [ op ] ; cb -> cb_msg . rpc_argp = cb ; cb -> cb_msg . rpc_resp = cb ; cb -> cb_ops = ops ; INIT_WORK ( & cb -> cb_work , nfsd4_run_cb_work ) ; cb -> cb_seq_status = 1 ; cb -> cb_need_restart = false ; } 